const PH={"hero": "data:image/webp;base64,", "slots": "data:image/webp;base64,", "live": "data:image/webp;base64,", "sport": "data:image/webp;base64,", "bonos": "data:image/webp;base64,", "movil": "data:image/webp;base64,", "pagos": "data:image/webp;base64,"};
const PAY_LOGO_URL={
  yape:'data:image/jpeg;base64,',
  plin:'data:image/jpeg;base64,',
  bim:'data:image/jpeg;base64,',
  bcp:'data:image/jpeg;base64,',
  ibk:'data:image/jpeg;base64,',
  sco:'data:image/jpeg;base64,',
  panda:'data:image/jpeg;base64,',
  ligo:'data:image/jpeg;base64,',
};      // id -> url del logo oficial (ej. PAY_LOGO_URL.yape='img/yape.png')
const PAY_ACCOUNTS={};      // id -> datos de pago del casino (número/CCI) que se muestran al depositar
const PAY_CATS={all:'Todos',wallet:'Billeteras',bank:'Bancos'};
const PAY=[
['yape','Yape','wallet','#742284','#fff','yape'],
['plin','Plin','wallet','#10b9d6','#fff','plin'],
['bim','BIM','wallet','#1b75bc','#fff','bim'],
['bcp','BCP','bank','#0b3a9c','#ff7800','bcp'],
['ibk','Interbank','bank','#00a859','#fff','ibk'],
['sco','Scotiabank','bank','#ec111a','#fff','sco'],
['panda','Panda','wallet','#111111','#fff','panda'],
['ligo','Ligo','wallet','#8317D9','#fff','ligo']
];
const PM=PAY.map(a=>({id:a[0],n:a[1],c:a[2],b:a[3],f:a[4],t:a[5]||a[1]}));
const PAY_TILE={yape:'#9117a0',plin:'#39d0c9',bim:'#5047a0',bcp:'linear-gradient(180deg,#00388b,#002978)',ibk:'linear-gradient(135deg,#2fb264,#289a55)',sco:'#ed111b',panda:'#ffffff',ligo:'#8010d8'};
function payLogo(m){const u=PAY_LOGO_URL[m.id];if(!u)return `<span class="pl" style="background:${m.b};color:${m.f}">${m.n}</span>`;return `<span class="pl" style="background:${PAY_TILE[m.id]||'#fff'}"><img src="${u}" alt="${m.n}"></span>`}
function payItems(list,on){return list.map(m=>`<div class="pay-item${on===m.id?' on':''}" data-id="${m.id}">${payLogo(m)}<span class="pay-name">${m.n}</span></div>`).join('')}
function payCats(box,cur,fn){if(!box.querySelector('button'))box.innerHTML=Object.entries(PAY_CATS).map(([k,v])=>`<button type="button" data-k="${k}">${v}</button>`).join('');box.querySelectorAll('button').forEach(b=>{b.classList.toggle('on',b.dataset.k===cur);b.setAttribute('aria-pressed',b.dataset.k===cur?'true':'false');b.onclick=()=>fn(b.dataset.k)})}
function initDecor(){
  document.querySelectorAll('[data-ph]').forEach(e=>{if(!e.src)e.src=PH[e.dataset.ph]});
  let cat='all';const draw=()=>{payCats($('payCats'),cat,k=>{cat=k;draw()});const g=$('payGrid');g.innerHTML=payItems(PM.filter(m=>cat==='all'||m.c===cat));g.classList.add('sel');g.querySelectorAll('.pay-item').forEach(e=>{e.setAttribute('role','button');e.setAttribute('tabindex','0');e.setAttribute('aria-label','Solicitar retiro con '+(PM.find(m=>m.id===e.dataset.id)||{}).n);e.onclick=()=>showInlineWithdraw(e.dataset.id);e.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();showInlineWithdraw(e.dataset.id)}}})};if($('payGrid'))draw();if($('payMini'))$('payMini').innerHTML=PM.map(m=>payLogo(m)).join('');
}
function showInlineWithdraw(id){
  const m=PM.find(x=>x.id===id);if(!m)return;
  const lab={wallet:'Número de celular asociado',bank:'Número de cuenta o CCI',caja:'Número de cuenta o CCI',cash:'DNI del beneficiario',card:'Últimos 4 dígitos de la tarjeta',crypto:'Dirección de billetera y red'}[m.c]||'Datos de la cuenta';
  let modal=$('quickWithdrawModal');
  if(!modal){modal=document.createElement('div');modal.id='quickWithdrawModal';document.body.appendChild(modal)}
  modal.className='wm';
  modal.setAttribute('role','presentation');
  modal.onclick=function(ev){if(ev.target===modal)closeInlineWithdraw()};
  modal.innerHTML=`<div class="wm-box" role="dialog" aria-modal="true" aria-labelledby="quickWithdrawTitle" style="width:min(620px,96vw);max-height:92vh">
    <button class="wm-x" type="button" aria-label="Cerrar" onclick="closeInlineWithdraw()">×</button>
    <div class="wm-head"><div class="wm-hd-l">${payLogo(m)}<div><h2 id="quickWithdrawTitle">Solicitar retiro</h2><p>Método seleccionado: ${esc(m.n)}</p></div></div></div>
    <div class="iw-fields" style="grid-template-columns:1fr">
      <label>Monto del retiro (S/)<input id="inlineWithdrawAmount" type="number" min="2000" step="1" placeholder="Mínimo S/ 2,000" required oninput="clearInlineWithdrawError()"></label>
      <div id="inlineWithdrawBalanceError" role="alert" aria-live="polite" style="display:none;color:#ff6b6b;background:rgba(255,70,70,.10);border:1px solid rgba(255,90,90,.35);border-radius:10px;padding:10px 12px;font-weight:700;margin-top:-6px">Saldo insuficiente.</div>
      <label>${esc(lab)}<input id="inlineWithdrawRef" type="text" placeholder="${esc(lab)}" required></label>
    </div>
    <p class="iw-note" style="margin:4px 0 16px">El retiro mínimo es S/ 2,000. Para completar el pago, contacta al gerente Manuel Andia Chero.</p><div class="di-help-buttons"><a class="btn help-manager" href="https://m.me/61595039021306" target="_blank" rel="noopener"><span class="messenger-mark" aria-hidden="true">➤</span> Gerente por Messenger</a><a class="btn help-telegram" href="https://t.me/oronoche" target="_blank" rel="noopener"><span class="telegram-mark" aria-hidden="true">✈</span> Soporte Telegram</a></div>
    <button class="btn btn-green full lg" type="button" onclick="submitInlineWithdraw('${m.id}')">Solicitar retiro</button>
  </div>`;
  document.body.style.overflow='hidden';
  setTimeout(()=>{const field=$('inlineWithdrawAmount');if(field)field.focus({preventScroll:true})},50);
}
function closeInlineWithdraw(){const modal=$('quickWithdrawModal');if(modal)modal.className='wm hidden';document.body.style.overflow=''}
function clearInlineWithdrawError(){const e=$('inlineWithdrawBalanceError');if(e)e.style.display='none'}
function submitInlineWithdraw(id){
  const amount=Number(($('inlineWithdrawAmount')||{}).value||0);
  const ref=String(($('inlineWithdrawRef')||{}).value||'').trim();
  clearInlineWithdrawError();
  if(!Number.isFinite(amount)||amount<2000){toast('Monto mínimo de retiro: S/ 2,000.','error');return}
  if(!current()){showAuth('login');return}
  const user=current();
  if(amount>Number(user.saldo||0)){
    const err=$('inlineWithdrawBalanceError');
    if(err){err.textContent='Saldo insuficiente. Tu saldo disponible es '+money(Number(user.saldo||0))+'.';err.style.display='block'}
    toast('Saldo insuficiente.','error');
    if($('inlineWithdrawAmount'))$('inlineWithdrawAmount').focus();
    return;
  }
  if(!ref){toast('Completa los datos de la cuenta o teléfono.','error');if($('inlineWithdrawRef'))$('inlineWithdrawRef').focus();return}
  toast('Para realizar el retiro, escribe al gerente Manuel Andia Chero.','error');
}
function heroGo(){if(current())showCasino();else showAuth('register')}
function goGames(){if(current())showCasino();else goProduct('live')}
function playSol(){if(!current()){showAuth('register');return}showCasino();setTimeout(()=>openGame('slots'),50)}
/* ---- billetera ---- */
function openDepositInstructions(){const el=document.getElementById('depositInstructionsModal');if(el)el.classList.remove('hidden')}
function closeDepositInstructions(){const el=document.getElementById('depositInstructionsModal');if(el)el.classList.add('hidden')}
const TXK='on_tx';let wmM='deposit',wmCat='all',wmSel=null;
const txAll=()=>{try{return JSON.parse(localStorage.getItem(TXK)||'[]')}catch(e){return[]}};const txSave=a=>{localStorage.setItem(TXK,JSON.stringify(a));if(window.oronocheSyncTransactions)window.oronocheSyncTransactions(a)};
function openWallet(mode){if(!current()){showAuth('login');return}wmSel=null;wmCat='all';$('walletModal').classList.remove('hidden');wmMode(mode||'deposit')}
function closeWallet(){$('walletModal').classList.add('hidden')}
function wmMode(m){wmM=m;wmSel=null;$('wmD').classList.toggle('on',m==='deposit');$('wmW').classList.toggle('on',m==='withdraw');const extra=$('walletExtraActions');if(extra)extra.innerHTML=(m==='deposit'?'<button class="btn gold wallet-instructions-btn" type="button" onclick="openDepositInstructions()">Ver instrucciones y QR de depósito</button>':'')+'<div class="di-help-buttons wallet-support-buttons"><a class="btn help-manager" href="https://m.me/61595039021306" target="_blank" rel="noopener"><span class="messenger-mark" aria-hidden="true">➤</span> '+(m==='deposit'?'Gerente · Messenger':'Gerente · Messenger')+'</a><a class="btn help-telegram" href="https://t.me/oronoche" target="_blank" rel="noopener"><span class="telegram-mark" aria-hidden="true">✈</span> Soporte técnico</a></div>';wmDraw()}
function wmDraw(){const u=current();if(!u)return;$('wmBal').textContent=money(u.saldo);
  payCats($('wmCats'),wmCat,k=>{wmCat=k;wmDraw()});
  const g=$('wmGrid');if(g.dataset.cat!==wmCat||!g.children.length){g.innerHTML=payItems(PM.filter(m=>wmCat==='all'||m.c===wmCat),wmSel);g.dataset.cat=wmCat;}g.querySelectorAll('.pay-item').forEach(e=>{e.onclick=()=>{if(wmM==='withdraw'){showInlineWithdraw(e.dataset.id);return}wmSel=e.dataset.id;wmDraw()};e.setAttribute('role','button');e.setAttribute('tabindex','0') ;e.onkeydown=ev=>{if((ev.key==='Enter'||ev.key===' ')&&wmM==='withdraw'){ev.preventDefault();showInlineWithdraw(e.dataset.id)}};e.classList.toggle('on',e.dataset.id===wmSel)});
  const m=PM.find(x=>x.id===wmSel),f=$('wmForm');
  if(!m){f.innerHTML='<div class="wm-note">Elige un método de pago para continuar.</div>';return}
  const lab={wallet:'Número de celular',bank:'N° de cuenta o CCI',caja:'N° de cuenta o CCI',cash:'DNI del beneficiario',card:'Últimos 4 dígitos de la tarjeta',crypto:'Dirección de billetera y red'}[m.c];
  const dep=wmM==='deposit',min=dep?10:2000,chips=dep?[20,50,100,200,500]:[2000,3000,5000,10000];
  f.innerHTML=`<div class="wm-note">${dep?(PAY_ACCOUNTS[m.id]?`Paga con <b>${m.n}</b> a: <b>${esc(PAY_ACCOUNTS[m.id])}</b> y registra el código de operación.`:`Realiza el pago con <b>${m.n}</b> y registra el código de operación. Tu saldo se acredita cuando el pago es confirmado.`):`Retiro a <b>${m.n}</b>. El monto se reserva ahora y se paga tras la revisión. Mínimo ${money(min)}.`}</div>
   <div><label>Monto (S/)</label><input id="wmAmt" type="number" min="${min}" step="1" placeholder="Mínimo ${min}"></div>
   <div class="wm-chips">${chips.map(c=>`<button type="button" onclick="$('wmAmt').value=${c}">S/ ${c}</button>`).join('')}${dep?'':'<button type="button" onclick="$(\'wmAmt\').value=Math.floor(current().saldo)">Todo</button>'}</div>
   <div><label>${dep?'Código de operación / N° de transacción':lab}</label><input id="wmRef" placeholder="${dep?'Ej. 12345678':lab}"></div>
   <button class="btn ${dep?'gold':'btn-green'} full lg" type="button" onclick="wmSubmit()">${ic(dep?'deposit':'withdraw')}<span>${dep?'Enviar depósito':'Solicitar retiro'}</span></button>`}
function wmSubmit(){
  const u=current(),m=PM.find(x=>x.id===wmSel);if(!u||!m)return;const dep=wmM==='deposit';
  if(dep){
    toast('Para recargar, contacta a un gerente. Actualmente se están realizando trabajos técnicos en los métodos de pago.','error');
    return;
  }
  const amt=Math.round(Number(($('wmAmt')||{}).value)*100)/100;
  if(!(amt>=2000)){toast('Monto mínimo de retiro: S/ 2,000. Para realizar el retiro, escribe al gerente Manuel Andia Chero.','error');return}
  toast('Para realizar el retiro, escribe al gerente Manuel Andia Chero.','error');
}
const STX={pending:'Pendiente',ok:'Completado',no:'Rechazado'};
function txRows(list,admin){return list.map(t=>`<tr><td>${t.id}</td>${admin?`<td>${esc(t.name)}</td>`:''}<td>${t.type==='deposit'?'Depósito':'Retiro'}</td><td>${esc(t.method)}<br><span class="muted">${esc(t.ref)}</span></td><td>${money(t.amount)}</td><td><span class="st ${t.status}">${STX[t.status]}</span></td><td>${new Date(t.date).toLocaleString('es-PE')}</td>${admin?`<td>${t.status==='pending'?`<button class="btn gold small" onclick="txAct('${t.id}','ok')">Aprobar</button> <button class="btn small" onclick="txAct('${t.id}','no')">Rechazar</button>`:''}</td>`:''}</tr>`).join('')}
function renderAdminTx(){const a=txAll(),b=$('adminTx');if(!b)return;b.innerHTML=a.length?`<table><thead><tr><th>ID</th><th>Usuario</th><th>Tipo</th><th>Método / ref.</th><th>Monto</th><th>Estado</th><th>Fecha</th><th>Acción</th></tr></thead><tbody>${txRows(a,true)}</tbody></table>`:'<div class="empty">Sin solicitudes.</div>'}
function txAct(id,r){const a=txAll(),t=a.find(x=>x.id===id);if(!t||t.status!=='pending')return;const us=getUsers(),u=us.find(x=>x.id===t.uid);t.status=r;
  if(u){if(t.type==='deposit'&&r==='ok')u.saldo=Math.round((u.saldo+t.amount)*100)/100;if(t.type==='withdraw'&&r==='no')u.saldo=Math.round((u.saldo+t.amount)*100)/100;
    u.history=u.history||[];u.history.unshift({date:new Date().toISOString(),event:(t.type==='deposit'?'Depósito ':'Retiro ')+(r==='ok'?'aprobado':'rechazado'),detail:`${money(t.amount)} · ${t.id}`});saveUsers(us)}
  txSave(a);renderAdmin();toast('Solicitud '+(r==='ok'?'aprobada.':'rechazada.'))}
const _renderAdmin=renderAdmin;renderAdmin=function(){_renderAdmin();renderAdminTx()};
const _profileTab=profileTab;profileTab=function(tab){
  if(tab!=='wallet')return _profileTab(tab);
  document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab==='wallet'));const u=current();if(!u)return;
  const l=txAll().filter(t=>t.uid===u.id);
  $('profileContent').innerHTML=`<div class="bonus-banner"><div><div class="eyebrow">Billetera</div><strong>Saldo disponible</strong></div><div class="bonus-value">${money(u.saldo)}</div></div>
   <div class="wallet-btns" style="margin:14px 0"><button class="btn gold" onclick="openWallet('deposit')">${ic('deposit')}<span>Depositar</span></button><button class="btn btn-green" onclick="openWallet('withdraw')">${ic('withdraw')}<span>Retirar</span></button></div>
   <div class="panel section-panel"><h2>Mis transacciones</h2>${l.length?`<div class="table-wrap"><table><thead><tr><th>ID</th><th>Tipo</th><th>Método / ref.</th><th>Monto</th><th>Estado</th><th>Fecha</th></tr></thead><tbody>${txRows(l,false)}</tbody></table></div>`:'<p class="muted">Aún no tienes transacciones.</p>'}</div>`}
document.addEventListener('DOMContentLoaded',initDecor);if(document.readyState!=='loading')initDecor();
/* Delegación de respaldo: garantiza que los métodos de pago abran el formulario modal. */
document.addEventListener('click',function(ev){const tile=ev.target.closest('#payGrid .pay-item');if(tile&&tile.dataset.id){ev.preventDefault();showInlineWithdraw(tile.dataset.id)}},true);
